INSERT INTO TblLugar( idl, nome_local, info, x, y, elevacao ) VALUES ( 1, 'Orjais (Orjais)', null, 40.3405155, -7.4066417, null ); 
INSERT INTO TblLugar( idl, nome_local, info, x, y, elevacao ) VALUES ( 2, 'Bouça (Cortes do Meio)', 'Bouça é uma aldeia com 228 habitantes (2011) que integra a freguesia de Cortes do Meio, no concelho da Covilhã, cidade da qual dista 16 km. ', 40.2684427, -7.5701097, null ); 
INSERT INTO TblLugar( idl, nome_local, info, x, y, elevacao ) VALUES ( 3, 'Covilhã (Conceição)', 'Conceição foi uma freguesia portuguesa do município da Covilhã, com 4,87 km² de área e 7 175 habitantes (2011). Densidade: 1 473,3 hab/km². A ela tinha sido agregada a antiga paróquia de São Bartolomeu[2]. Foi extinta em 2013, no âmbito de uma reforma administrativa nacional, tendo sido agregada às freguesias de Santa Maria, São Martinho, São Pedro e Canhoso, para formar uma nova freguesia denominada União das Freguesias de Covilhã e Canhoso da qual é a sede.[3] ', 40.2868631, -7.4982043, null ); 
INSERT INTO TblLugar( idl, nome_local, info, x, y, elevacao ) VALUES ( 4, 'Portela (Vila do Carvalho)', 'Aldeia da antiga freguesia da Vila de carvalho do município da Covilhã, a norte da sede de concelho, com 9,93 km² de área e 1 741 habitantes (2011). A sua densidade demográfica é de 175,3 hab/km². Foi elevada à categoria de vila no dia 24 de Agosto de 1989. Foi extinta em 2013, no âmbito de uma reforma administrativa nacional, tendo sido agregada à freguesia de Cantar-Galo, para formar uma nova freguesia denominada União das Freguesias de Cantar-Galo e Vila do Carvalho.', 40.3204249, -7.4831337, null ); 
INSERT INTO TblLugar( idl, nome_local, info, x, y, elevacao ) VALUES ( 5, 'Covilhã (Santa Maria)', 'Conceição foi uma freguesia portuguesa do município da Covilhã, com 4,87 km² de área e 7 175 habitantes (2011). Densidade: 1 473,3 hab/km². A ela tinha sido agregada a antiga paróquia de São Bartolomeu. Foi extinta em 2013, no âmbito de uma reforma administrativa nacional, tendo sido agregada às freguesias de Santa Maria, São Martinho, São Pedro e Canhoso, para formar uma nova freguesia denominada União das Freguesias de Covilhã e Canhoso da qual é a sede.', 40.2929584, -7.5330808, null ); 
INSERT INTO TblLugar( idl, nome_local, info, x, y, elevacao ) VALUES ( 6, 'Teixoso (Teixoso)', null, 40.3081514, -7.4282316, null ); 
INSERT INTO TblLugar( idl, nome_local, info, x, y, elevacao ) VALUES ( 7, 'Cortes de Cima (Cortes do Meio)', null, 40.2474590, -7.5824281, null ); 
INSERT INTO TblLugar( idl, nome_local, info, x, y, elevacao ) VALUES ( 8, 'Vales do Rio (Vales do Rio)', 'Vales do Rio foi uma freguesia portuguesa do município da Covilhã, com 5,12 km² de área e 674 habitantes (2011). A sua densidade populacional é de 131,6 hab/km². Foi criada por Decreto de Lei em 9 de Julho de 1976. Foi extinta em 2013, no âmbito de uma reforma administrativa nacional, tendo sido agregada à freguesia de Peso, para formar uma nova freguesia denominada União das Freguesias de Peso e Vales do Rio com a sede em Peso.', 40.2013131, -7.5459149, null ); 
INSERT INTO TblLugar( idl, nome_local, info, x, y, elevacao ) VALUES ( 9, 'Erada (Erada)', 'Erada é uma freguesia portuguesa do município da Covilhã, com 43,4 km² de área e 574 habitantes (2021). A sua densidade populacional é de 16,3 hab/km² e pertence à rede de Aldeias de Montanha.', 40.2251430, -7.6486611, null ); 
INSERT INTO TblLugar( idl, nome_local, info, x, y, elevacao ) VALUES ( 10, 'Sarzedo (Sarzedo)', 'Sarzedo foi uma freguesia portuguesa do município da Covilhã, com 11,07 km² de área e 130 habitantes (2011). A sua densidade populacional é de 11,7 hab/km². Foi sede de um pequeno município extinto em 1836. Era composto apenas por uma freguesia e tinha, em 1801, 430 habitantes. Esteve incorporado no concelho de Valhelhas entre 1836 e 1855. Foi extinta em 2013, no âmbito de uma reforma administrativa nacional, tendo sido agregada à freguesia de Teixoso, para formar uma nova freguesia denominada União das Freguesias de Teixoso e Sarzedo.', 40.2417889, -8.0709500, null ); 
INSERT INTO TblLugar( idl, nome_local, info, x, y, elevacao ) VALUES ( 11, 'Barreira (Vila do Carvalho)', 'Pequena localidade nos arredores da Vila do Carvalho', 40.3100906, -7.4870069, null ); 
INSERT INTO TblLugar( idl, nome_local, info, x, y, elevacao ) VALUES ( 12, 'Peso (Peso)', 'Peso foi uma freguesia portuguesa do município da Covilhã, com 10,77 km² de área e 737 habitantes (2011). A sua densidade populacional é de 68,4 hab/km². Foi extinta em 2013, no âmbito de uma reforma administrativa nacional, tendo sido agregada à freguesia de Vales do Rio, para formar uma nova freguesia denominada União das Freguesias de Peso e Vales do Rio da qual é a sede.', 40.2202997, -7.5731619, null ); 
INSERT INTO TblLugar( idl, nome_local, info, x, y, elevacao ) VALUES ( 13, 'Vale da Cerdeira (São Jorge da Beira)', null, 40.1919186, -7.7620970, null ); 
INSERT INTO TblLugar( idl, nome_local, info, x, y, elevacao ) VALUES ( 14, 'Barroca Grande (Aldeia de São Francisco de Assis)', 'Barroca Grande é uma aldeia da freguesia de Aldeia de São Francisco de Assis que é uma freguesia portuguesa do município da Covilhã, com 16,08 km² de área e 490 habitantes (2021). A sua densidade populacional é de 39,3 hab/km². Anteriormente designada por Bodelhão, foi povoação anexa da freguesia de Barroca do concelho do Fundão, até 1895 e esteve anexada à extinta freguesia de Ourondo até 1901. A freguesia é composta ainda pelas aldeias anexas de Barroca Grande e Parada.', 40.1553774, -7.7475851, null ); 
INSERT INTO TblLugar( idl, nome_local, info, x, y, elevacao ) VALUES ( 15, 'Tortozendo (Tortosendo)', 'A vila de Tortosendo (antigamente Tortozendo) é uma freguesia portuguesa e uma das 31 freguesias do município da Covilhã, com 17,75 km² de área e cerca de 5 219 habitantes (2021). A sua densidade populacional é de 317 hab/km².', 40.2384026, -7.5127992, null ); 
INSERT INTO TblLugar( idl, nome_local, info, x, y, elevacao ) VALUES ( 16, 'Casal de Santa Terezinha (São Jorge da Beira)', null, 40.1676446, -7.7842760, null ); 
INSERT INTO TblLugar( idl, nome_local, info, x, y, elevacao ) VALUES ( 17, 'Unhais da Serra (Unhais da Serra)', 'Unhais da Serra é uma freguesia portuguesa do município da Covilhã, com 29,93 km² de área e 1 050 habitantes (2021). A sua densidade populacional é de 46,7 hab/km².', 40.2751863, -7.6220391, null ); 
INSERT INTO TblLugar( idl, nome_local, info, x, y, elevacao ) VALUES ( 18, 'Canhoso (Teixoso)', 'Canhoso é uma freguesia portuguesa do município da Covilhã, com 6,87 km² de área e 2 237 habitantes (2011). A sua densidade populacional é de 325,6 hab/km². A freguesia de Canhoso foi criada em 20 de Junho de 1997 pela Lei 24/97 por desanexação de territórios das antigas freguesias de Vila do Carvalho, Cantar-Galo, Conceição e Teixoso. Foi extinta em 2013, no âmbito de uma reforma administrativa nacional sendo agregada às freguesias de Conceição, Santa Maria, São Martinho e São Pedro, para formar uma nova freguesia denominada União das Freguesias de Covilhã e Canhoso. A sua principal colectividade é Grupo Desportivo Águias do Canhoso.', 40.2950310, -7.4802858, null ); 
INSERT INTO TblLugar( idl, nome_local, info, x, y, elevacao ) VALUES ( 19, 'Paul (Paul)', 'Paul é uma freguesia portuguesa do município da Covilhã, com 23,99 km² de área e 1 365 habitantes (2021) e densidade populacional de 67,7 hab/km². Em 1989 foi elevada à categoria de vila', 40.2011531, -7.6368259, null ); 
INSERT INTO TblLugar( idl, nome_local, info, x, y, elevacao ) VALUES ( 20, 'Terra da Senhora (Unhais da Serra)', null, 40.2523137, -7.6297679, null ); 
INSERT INTO TblLugar( idl, nome_local, info, x, y, elevacao ) VALUES ( 21, 'Relvas (Ourondo)', 'aldeia da antiga freguesia de Ourondo, que foi uma freguesia portuguesa do município da Covilhã, com 7,09 km² de área e 372 habitantes (2011). A sua densidade populacional é de 52,5 hab/km². Foi extinta em 2013, no âmbito de uma reforma administrativa nacional, tendo sido agregada à freguesia de Casegas, para formar uma nova freguesia denominada União das Freguesias de Casegas e Ourondo com a sede em Casegas', 40.1570223, -7.6768210, null ); 
INSERT INTO TblLugar( idl, nome_local, info, x, y, elevacao ) VALUES ( 22, 'Covilhã (São Pedro)', 'São Pedro foi uma freguesia portuguesa do município da Covilhã, com 2,66 km² de área e 2 225 habitantes (2011). Densidade: 836,5 hab/km². Foi extinta em 2013, no âmbito de uma reforma administrativa nacional, tendo sido agregada às freguesias de Conceição, Santa Maria, São Martinho e Canhoso, para formar uma nova freguesia denominada União das Freguesias de Covilhã e Canhoso com a sede em Conceição.', 40.2771340, -7.4867404, null ); 
INSERT INTO TblLugar( idl, nome_local, info, x, y, elevacao ) VALUES ( 23, 'Trigais (Erada)', 'Erada é uma freguesia portuguesa do município da Covilhã, com 43,4 km² de área e 574 habitantes (2021). A sua densidade populacional é de 16,3 hab/km².', null, null, null ); 
INSERT INTO TblLugar( idl, nome_local, info, x, y, elevacao ) VALUES ( 24, 'Vila do Carvalho (Vila do Carvalho)', 'Vila do Carvalho foi uma freguesia portuguesa do município da Covilhã, localizada a norte da sede de concelho, com 9,93 km² de área e 1 741 habitantes (2011). A sua densidade demográfica é de 175,3 hab/km². Foi elevada à categoria de vila no dia 24 de Agosto de 1989. Foi extinta em 2013, no âmbito de uma reforma administrativa nacional, tendo sido agregada à freguesia de Cantar-Galo, para formar uma nova freguesia denominada União das Freguesias de Cantar-Galo e Vila do Carvalho da qual é a sede.', null, null, null ); 
INSERT INTO TblLugar( idl, nome_local, info, x, y, elevacao ) VALUES ( 25, 'Cantar-Galo (Cantar-Galo)', 'Foi uma freguesia portuguesa do município da Covilhã, com 5,87 km² de área e 2 233 habitantes (2011). A sua densidade populacional é de 380,4 hab/km². Foi extinta em 2013, no âmbito de uma reforma administrativa nacional, tendo sido agregada à freguesia de Vila do Carvalho, para formar uma nova freguesia denominada União das Freguesias de Cantar-Galo e Vila do Carvalho com a sede em Vila do Carvalho.', 40.3047552, -7.5367529, 1006.00 ); 
INSERT INTO TblLugar( idl, nome_local, info, x, y, elevacao ) VALUES ( 26, 'Vale das Donas (Tortosendo)', 'A vila de Tortosendo (antigamente Tortozendo) é uma freguesia portuguesa e uma das 31 freguesias do município da Covilhã, com 17,75 km² de área e cerca de 5 219 habitantes (2021). A sua densidade populacional é de 317 hab/km².', 40.2477945, -7.5038266, 460.00 ); 
