INSERT INTO TblLugar( idl, nome_local, info, x, y, elevacao ) VALUES ( 28, 'Boidobra (Boidobra)', 'Boidobra é uma freguesia portuguesa do município da Covilhã, com 16,26 km² de área e 3 173 habitantes (2021). A sua densidade populacional é de 199,6 hab/km². Com origens referenciadas ao século XII, em 20 de maio de 1993, foi elevada à categoria de Vila', 40.2538817, -7.4908275, 429.00 ); 
INSERT INTO TblLugar( idl, nome_local, info, x, y, elevacao ) VALUES ( 29, 'Covilhã (São Martinho)', 'São Martinho foi uma freguesia portuguesa do município da Covilhã, com 9,57 km² de área e 4 165 habitantes (2011). A sua densidade populacional é de 435,2 hab/km². Foi extinta em 2013, no âmbito de uma reforma administrativa nacional, tendo sido agregada às freguesias de Conceição, Santa Maria, São Pedro e Canhoso, para formar uma nova freguesia denominada União das Freguesias de Covilhã e Canhoso com a sede em Conceição.', 40.2802025, -7.5238747, null ); 
